-- Migration 001: Full Schema v2.0 + v7 updates
-- Run: psql $DATABASE_URL -f db/migrations/001_initial_schema.sql

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TYPE course_period_status AS ENUM ('pending_payment','payment_anomaly','active','completed','refunded');
CREATE TYPE session_status AS ENUM ('pending_group_confirm','confirmed','completed','cancelled_normal','cancelled_penalty');
CREATE TYPE slot_status AS ENUM ('available','pending_group_confirm','booked','blocked');
CREATE TYPE enrollment_status AS ENUM ('active','transferred_out');
CREATE TYPE course_plan_status AS ENUM ('draft','published');
CREATE TYPE session_record_status AS ENUM ('draft','published');
CREATE TYPE promotion_type AS ENUM ('PERCENTAGE','FIXED_AMOUNT','COUPON_CODE');
CREATE TYPE threshold_type AS ENUM ('PERIOD_COUNT','AMOUNT');
CREATE TYPE applicable_scope AS ENUM ('ALL','COURSE_TYPE','VENUE');
CREATE TYPE referral_status AS ENUM ('pending','registered','experience_purchased','experience_completed','full_course_purchased','reward_issued');
CREATE TYPE transfer_status AS ENUM ('pending_review','approved','rejected');
CREATE TYPE alert_status AS ENUM ('pending','reviewed','no_issue','resolved');
CREATE TYPE renew_intention AS ENUM ('yes','no','considering');
CREATE TYPE staff_role_type AS ENUM ('system_admin','manager','counter');

CREATE TABLE system_settings (key VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL, description TEXT, updated_at TIMESTAMPTZ DEFAULT NOW(), updated_by UUID);
CREATE TABLE venues (id VARCHAR(10) PRIMARY KEY, name VARCHAR(100) NOT NULL, full_name VARCHAR(200), full_address TEXT, bank_institution_code VARCHAR(10), bank_institution_name VARCHAR(100), bank_branch_code VARCHAR(10), bank_branch_name VARCHAR(100), account_holder VARCHAR(100), account_number VARCHAR(50), is_active BOOLEAN NOT NULL DEFAULT TRUE, last_synced_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE venue_line_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venue_id VARCHAR(10) NOT NULL REFERENCES venues(id) ON DELETE CASCADE, channel_access_token TEXT NOT NULL, channel_secret VARCHAR(200), line_at_display_name VARCHAR(100), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(venue_id));
CREATE TABLE staff_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ragic_employee_id VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE, password_hash VARCHAR(255), role staff_role_type NOT NULL, venue_id VARCHAR(10) REFERENCES venues(id), is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_staff_role ON staff_roles(role);
CREATE TABLE parents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), line_uid VARCHAR(100) UNIQUE, phone VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, gender VARCHAR(10), email VARCHAR(255), primary_venue_id VARCHAR(10) REFERENCES venues(id), service_unit VARCHAR(100), employee_id VARCHAR(50), ragic_record_id VARCHAR(50) UNIQUE, last_synced_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_parents_phone ON parents(phone); CREATE INDEX idx_parents_line_uid ON parents(line_uid);
CREATE TABLE students (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), parent_id UUID NOT NULL REFERENCES parents(id) ON DELETE RESTRICT, id_number VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, gender VARCHAR(10), birth_date DATE, blood_type VARCHAR(5), ragic_record_id VARCHAR(50) UNIQUE, last_synced_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_students_parent_id ON students(parent_id);
CREATE TABLE coaches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ragic_employee_id VARCHAR(50) NOT NULL UNIQUE, employee_number VARCHAR(50) UNIQUE, name VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL UNIQUE, line_uid VARCHAR(100) UNIQUE, email VARCHAR(255), specialties TEXT[], is_senior BOOLEAN NOT NULL DEFAULT FALSE, pricing_multiplier DECIMAL(5,2) NOT NULL DEFAULT 1.00, bio_rich_text TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, last_synced_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_coaches_is_active ON coaches(is_active);
CREATE TABLE coach_bio_media (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), coach_id UUID NOT NULL REFERENCES coaches(id) ON DELETE CASCADE, media_type VARCHAR(10) NOT NULL DEFAULT 'image', storage_url TEXT NOT NULL, alt_text VARCHAR(200), sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE promotions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(200) NOT NULL, description TEXT, type promotion_type NOT NULL, discount_value DECIMAL(10,4) NOT NULL, coupon_code VARCHAR(50) UNIQUE, min_threshold_type threshold_type, min_threshold_value DECIMAL(10,2), applicable_scope applicable_scope NOT NULL DEFAULT 'ALL', applicable_course_types INTEGER[], applicable_venue_ids VARCHAR(10)[], start_date DATE NOT NULL, end_date DATE NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, max_uses INTEGER, current_uses INTEGER NOT NULL DEFAULT 0, created_by UUID REFERENCES staff_roles(id), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), CONSTRAINT check_discount CHECK (discount_value > 0), CONSTRAINT check_dates CHECK (end_date >= start_date));
CREATE INDEX idx_promotions_dates ON promotions(start_date, end_date);
CREATE TABLE promotion_usages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), promotion_id UUID NOT NULL REFERENCES promotions(id) ON DELETE RESTRICT, course_period_id UUID NOT NULL, original_price DECIMAL(10,2) NOT NULL, discount_amount DECIMAL(10,2) NOT NULL, final_price DECIMAL(10,2) NOT NULL, used_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(promotion_id, course_period_id));
CREATE TABLE course_periods (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), coach_id UUID NOT NULL REFERENCES coaches(id) ON DELETE RESTRICT, venue_id VARCHAR(10) NOT NULL REFERENCES venues(id) ON DELETE RESTRICT, course_type INTEGER NOT NULL CHECK (course_type >= 1), total_sessions INTEGER NOT NULL DEFAULT 6, used_sessions INTEGER NOT NULL DEFAULT 0, expires_at DATE NOT NULL, original_price DECIMAL(10,2) NOT NULL, final_price DECIMAL(10,2) NOT NULL, transfer_last_5 VARCHAR(5), payment_status VARCHAR(20) NOT NULL DEFAULT 'pending', payment_confirmed_at TIMESTAMPTZ, payment_confirmed_by UUID REFERENCES staff_roles(id), status course_period_status NOT NULL DEFAULT 'pending_payment', is_experience_course BOOLEAN NOT NULL DEFAULT FALSE, referral_record_id UUID, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), CONSTRAINT check_sessions CHECK (used_sessions >= 0 AND used_sessions <= total_sessions));
CREATE INDEX idx_periods_coach ON course_periods(coach_id); CREATE INDEX idx_periods_status ON course_periods(status); CREATE INDEX idx_periods_expires ON course_periods(expires_at);
ALTER TABLE promotion_usages ADD CONSTRAINT fk_promo_usage_period FOREIGN KEY (course_period_id) REFERENCES course_periods(id) ON DELETE CASCADE;
CREATE TABLE payment_audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE CASCADE, action VARCHAR(40) NOT NULL, from_status VARCHAR(20), to_status VARCHAR(20), transfer_last_5 VARCHAR(5), note TEXT, performed_by UUID REFERENCES staff_roles(id), performed_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_payment_audit_period ON payment_audit_logs(course_period_id);
CREATE TABLE course_period_enrollments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id) ON DELETE RESTRICT, status enrollment_status NOT NULL DEFAULT 'active', enrolled_at TIMESTAMPTZ DEFAULT NOW(), transferred_at TIMESTAMPTZ, transferred_to_enrollment_id UUID REFERENCES course_period_enrollments(id), UNIQUE(course_period_id, student_id));
CREATE TABLE coach_availability_slots (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), coach_id UUID NOT NULL REFERENCES coaches(id) ON DELETE CASCADE, venue_id VARCHAR(10) NOT NULL REFERENCES venues(id) ON DELETE RESTRICT, start_at TIMESTAMPTZ NOT NULL, duration_minutes INTEGER NOT NULL DEFAULT 60, status slot_status NOT NULL DEFAULT 'available', booked_session_id UUID, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(coach_id, start_at));
CREATE INDEX idx_slots_coach ON coach_availability_slots(coach_id); CREATE INDEX idx_slots_start ON coach_availability_slots(start_at); CREATE INDEX idx_slots_status ON coach_availability_slots(status);
CREATE TABLE course_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE CASCADE, availability_slot_id UUID REFERENCES coach_availability_slots(id), scheduled_at TIMESTAMPTZ NOT NULL, duration_minutes INTEGER NOT NULL DEFAULT 60, status session_status NOT NULL DEFAULT 'confirmed', initiated_by_parent_id UUID REFERENCES parents(id), group_confirm_status JSONB, group_confirm_deadline TIMESTAMPTZ, auto_confirmed_at TIMESTAMPTZ, confirmed_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, cancelled_by_parent_id UUID REFERENCES parents(id), cancellation_type VARCHAR(10), cancellation_reason TEXT, session_deducted BOOLEAN NOT NULL DEFAULT FALSE, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_sessions_period ON course_sessions(course_period_id); CREATE INDEX idx_sessions_scheduled ON course_sessions(scheduled_at); CREATE INDEX idx_sessions_status ON course_sessions(status);
ALTER TABLE coach_availability_slots ADD CONSTRAINT fk_slot_session FOREIGN KEY (booked_session_id) REFERENCES course_sessions(id);
CREATE TABLE checkin_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_session_id UUID NOT NULL REFERENCES course_sessions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id) ON DELETE RESTRICT, checked_in_by_student_id UUID NOT NULL REFERENCES students(id), is_auto_linked BOOLEAN NOT NULL DEFAULT FALSE, checked_in_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(course_session_id, student_id));
CREATE TABLE course_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE CASCADE, goals TEXT, expected_outcomes TEXT, learning_schedule TEXT, initial_assessment TEXT, notes TEXT, status course_plan_status NOT NULL DEFAULT 'draft', published_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(course_period_id));
CREATE TABLE session_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_session_id UUID NOT NULL REFERENCES course_sessions(id) ON DELETE CASCADE, content_summary TEXT, performance_evaluation TEXT, next_session_direction TEXT, homework TEXT, remarks TEXT, status session_record_status NOT NULL DEFAULT 'draft', published_at TIMESTAMPTZ, last_modified_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(course_session_id));
CREATE TABLE session_record_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_record_id UUID NOT NULL REFERENCES session_records(id) ON DELETE CASCADE, version_number INTEGER NOT NULL, content_snapshot JSONB NOT NULL, modified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(session_record_id, version_number));
CREATE TABLE session_record_media (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_record_id UUID NOT NULL REFERENCES session_records(id) ON DELETE CASCADE, media_type VARCHAR(10) NOT NULL, storage_url TEXT NOT NULL, caption TEXT, file_size_bytes BIGINT, uploaded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE session_record_tags (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tag_category VARCHAR(20) NOT NULL, tag_text VARCHAR(50) NOT NULL, auto_generated_template TEXT, is_system_default BOOLEAN NOT NULL DEFAULT TRUE, coach_id UUID REFERENCES coaches(id) ON DELETE CASCADE, sort_order INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE course_evaluations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE CASCADE, parent_id UUID NOT NULL REFERENCES parents(id) ON DELETE RESTRICT, teaching_quality SMALLINT CHECK (teaching_quality BETWEEN 1 AND 5), communication_attitude SMALLINT CHECK (communication_attitude BETWEEN 1 AND 5), student_progress SMALLINT CHECK (student_progress BETWEEN 1 AND 5), overall_satisfaction SMALLINT CHECK (overall_satisfaction BETWEEN 1 AND 5), text_feedback TEXT, renew_intention renew_intention, invited_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), submitted_at TIMESTAMPTZ, reminder_sent_at TIMESTAMPTZ, UNIQUE(course_period_id, parent_id));
CREATE TABLE referral_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), referrer_parent_id UUID NOT NULL REFERENCES parents(id) ON DELETE RESTRICT, referee_phone VARCHAR(20) NOT NULL, referee_parent_id UUID REFERENCES parents(id), referred_coach_id UUID NOT NULL REFERENCES coaches(id) ON DELETE RESTRICT, referral_code VARCHAR(50) NOT NULL UNIQUE, status referral_status NOT NULL DEFAULT 'pending', experience_course_period_id UUID REFERENCES course_periods(id), full_course_period_id UUID REFERENCES course_periods(id), reward_promotion_id UUID REFERENCES promotions(id), experience_completed_at TIMESTAMPTZ, reward_issued_at TIMESTAMPTZ, expires_at DATE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE course_periods ADD CONSTRAINT fk_periods_referral FOREIGN KEY (referral_record_id) REFERENCES referral_records(id);
CREATE TABLE transfer_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE RESTRICT, from_enrollment_id UUID NOT NULL REFERENCES course_period_enrollments(id), to_student_id UUID NOT NULL REFERENCES students(id) ON DELETE RESTRICT, to_enrollment_id UUID REFERENCES course_period_enrollments(id), sessions_transferred INTEGER NOT NULL, transfer_fee DECIMAL(10,2) NOT NULL DEFAULT 500, status transfer_status NOT NULL DEFAULT 'pending_review', requested_by_parent_id UUID NOT NULL REFERENCES parents(id), reviewed_by UUID REFERENCES staff_roles(id), reviewed_at TIMESTAMPTZ, rejection_reason TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE refund_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE RESTRICT, sessions_used INTEGER NOT NULL, sessions_remaining INTEGER NOT NULL, original_price DECIMAL(10,2) NOT NULL, refund_fee_rate DECIMAL(5,4) NOT NULL, refund_fee_amount DECIMAL(10,2) NOT NULL, refund_amount DECIMAL(10,2) NOT NULL, reason TEXT NOT NULL, processed_by UUID NOT NULL REFERENCES staff_roles(id), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE chat_rooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_period_id UUID NOT NULL REFERENCES course_periods(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(course_period_id));
CREATE TABLE messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), chat_room_id UUID NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE, sender_type VARCHAR(10) NOT NULL, sender_id UUID NOT NULL, message_type VARCHAR(10) NOT NULL DEFAULT 'text', content TEXT, media_url TEXT, media_filename VARCHAR(255), media_size_bytes BIGINT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_messages_room ON messages(chat_room_id); CREATE INDEX idx_messages_created ON messages(created_at DESC);
CREATE TABLE keyword_alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), chat_room_id UUID NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE, message_id UUID NOT NULL REFERENCES messages(id) ON DELETE CASCADE, triggered_keyword VARCHAR(100) NOT NULL, status alert_status NOT NULL DEFAULT 'pending', reviewed_by UUID REFERENCES staff_roles(id), reviewed_at TIMESTAMPTZ, review_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE keyword_list (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), keyword VARCHAR(100) NOT NULL UNIQUE, category VARCHAR(30) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE course_intros (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), course_type INTEGER NOT NULL, title VARCHAR(200), description TEXT, target_audience TEXT, feature_tags TEXT[], cover_image_url TEXT, is_published BOOLEAN NOT NULL DEFAULT FALSE, updated_by UUID REFERENCES staff_roles(id), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(course_type), CONSTRAINT check_intro_course_type CHECK (course_type >= 1));
CREATE TABLE notification_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), notification_type VARCHAR(50) NOT NULL, recipient_type VARCHAR(10) NOT NULL, recipient_id UUID NOT NULL, venue_id VARCHAR(10) REFERENCES venues(id), related_entity_type VARCHAR(30), related_entity_id UUID, payload JSONB, sent_at TIMESTAMPTZ DEFAULT NOW(), status VARCHAR(20) NOT NULL DEFAULT 'sent', error_message TEXT);
CREATE INDEX idx_notif_recipient ON notification_logs(recipient_type, recipient_id);

CREATE VIEW v_course_period_summary AS SELECT cp.id, cp.coach_id, co.name AS coach_name, co.is_senior, co.pricing_multiplier, cp.venue_id, v.name AS venue_name, cp.course_type, cp.total_sessions, cp.used_sessions, (cp.total_sessions - cp.used_sessions) AS remaining_sessions, cp.expires_at, cp.status, cp.final_price, cp.is_experience_course, cp.created_at FROM course_periods cp JOIN coaches co ON cp.coach_id = co.id JOIN venues v ON cp.venue_id = v.id;
CREATE VIEW v_coach_weekly_schedule AS SELECT cs.id AS session_id, cp.coach_id, co.name AS coach_name, cp.venue_id, v.name AS venue_name, cp.course_type, cs.scheduled_at, cs.duration_minutes, cs.status, ARRAY_AGG(s.name ORDER BY s.name) AS student_names, COUNT(s.id) AS student_count FROM course_sessions cs JOIN course_periods cp ON cs.course_period_id = cp.id JOIN coaches co ON cp.coach_id = co.id JOIN venues v ON cp.venue_id = v.id JOIN course_period_enrollments cpe ON cpe.course_period_id = cp.id AND cpe.status = 'active' JOIN students s ON cpe.student_id = s.id WHERE cs.status IN ('confirmed','completed') GROUP BY cs.id, cp.coach_id, co.name, cp.venue_id, v.name, cp.course_type, cs.scheduled_at, cs.duration_minutes, cs.status;
CREATE VIEW v_coach_evaluation_avg AS SELECT cp.coach_id, co.name AS coach_name, co.is_senior, co.pricing_multiplier, COUNT(ce.id) AS total_evaluations, ROUND(AVG(ce.teaching_quality),2) AS avg_teaching_quality, ROUND(AVG(ce.communication_attitude),2) AS avg_communication, ROUND(AVG(ce.student_progress),2) AS avg_student_progress, ROUND(AVG(ce.overall_satisfaction),2) AS avg_overall, COUNT(CASE WHEN ce.renew_intention='yes' THEN 1 END) AS renew_yes, COUNT(CASE WHEN ce.renew_intention='no' THEN 1 END) AS renew_no, COUNT(CASE WHEN ce.renew_intention='considering' THEN 1 END) AS renew_considering FROM course_evaluations ce JOIN course_periods cp ON ce.course_period_id = cp.id JOIN coaches co ON cp.coach_id = co.id WHERE ce.submitted_at IS NOT NULL GROUP BY cp.coach_id, co.name, co.is_senior, co.pricing_multiplier;
CREATE VIEW v_coach_available_slots AS SELECT cas.id, cas.coach_id, co.name AS coach_name, cas.venue_id, v.name AS venue_name, cas.start_at, cas.duration_minutes, cas.status, cas.notes, (cas.start_at + (cas.duration_minutes || ' minutes')::interval) AS end_at FROM coach_availability_slots cas JOIN coaches co ON cas.coach_id = co.id JOIN venues v ON cas.venue_id = v.id;
